Algoritmo Triangulo
  Definir a Como Entero;
  Definir b Como Entero;
  Definir c Como Entero;
  Leer a;
  Leer b;
  Leer c;
  Si a >= b + c O b >= a + c O c >= a + b Entonces
    Escribir "no es triángulo";
  Sino
    Si a = b Y b = c Entonces
      Escribir "equilátero";
    Sino
      Si a = b O b = c O a = c Entonces
        Escribir "isósceles";
      Sino
        Escribir "escaleno";
      FinSi
    FinSi
  FinSi
FinAlgoritmo
